import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem117 corrige só a oferta identificada e preserva os campos operacionais',()=>{for(const [id,titulo,expected,link] of [["nfzTOT5XTvnh8Q8DyLvb","Tênis Masculino Elevation Fila","Tênis Masculino Elevation Fila","https://www.mercadolivre.com.br/up/MLBU3679312383?pdp_filters=item_id%3AMLB6067481206"],["nkBZlP0jQEwoMIj6VDbG","Capa Chuva Motoqueiro Pvc Impermeável Motoboy Emborrachada","Capa de chuva Brascamp em PVC para motociclista","https://produto.mercadolivre.com.br/MLB-5298350806-capa-chuva-motoqueiro-pvc-impermeavel-motoboy-emborrachada-_JM?searchVariation=182988333362"],["NQyo56LcUgwwA2tz8YCF","Tênis Mizuno Wave Dynasty 5 Masculino Treino Original","Tênis masculino Mizuno Wave Dynasty 5 — modelo anunciado","https://produto.mercadolivre.com.br/MLB-3384814517-tnis-mizuno-wave-dynasty-5-masculino-treino-original-_JM?searchVariation=179111328315"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).titulo,titulo);}});
